    #[test]
    fn creates_schema_and_is_idempotent() {
        let tmp = tempfile::tempdir().unwrap();
        let p = tmp.path().join("b.db");
        let c = open_writer(&p).unwrap();
        assert_eq!(ingest_offset(&c).unwrap(), 0);
        set_ingest_offset(&c, 1234).unwrap();
        drop(c);
        let c = open_writer(&p).unwrap();
        assert_eq!(ingest_offset(&c).unwrap(), 1234);
        let r = open_reader(&p).unwrap();
        assert_eq!(ingest_offset(&r).unwrap(), 1234);
        assert!(r.execute("UPDATE ingest_state SET log_offset = 0", []).is_err());
    }

    #[test]
    fn fts_triggers_keep_index_in_sync() {
        let tmp = tempfile::tempdir().unwrap();
        let c = open_writer(&tmp.path().join("b.db")).unwrap();
        c.execute(
            "INSERT INTO sessions (app, window, started_at, reconstructed_text)
             VALUES ('a', 'w', '2026-01-01T00:00:00.000Z', 'the migration is blocked')",
            [],
        )
        .unwrap();
        let hits = |q: &str| -> i64 {
            c.query_row(
                "SELECT count(*) FROM sessions_fts WHERE sessions_fts MATCH ?1",
                [q],
                |r| r.get(0),
            )
            .unwrap()
        };
        assert_eq!(hits("migration"), 1);
        c.execute("UPDATE sessions SET reconstructed_text = 'nothing here'", []).unwrap();
        assert_eq!(hits("migration"), 0);
        assert_eq!(hits("nothing"), 1);
        c.execute("DELETE FROM sessions", []).unwrap();
        assert_eq!(hits("nothing"), 0);
    }

    #[test]
    fn checkpoint_seek() {
        let tmp = tempfile::tempdir().unwrap();
        let c = open_writer(&tmp.path().join("b.db")).unwrap();
        insert_checkpoint(&c, "*", "2026-01-01T00:00:00.000Z", 0).unwrap();
        insert_checkpoint(&c, "*", "2026-01-01T00:00:05.000Z", 500).unwrap();
        insert_checkpoint(&c, "*", "2026-01-01T00:00:10.000Z", 900).unwrap();
        insert_checkpoint(&c, "*", "2026-01-01T00:00:10.000Z", 999).unwrap(); // ignored duplicate
        assert_eq!(seek_offset_before(&c, "2026-01-01T00:00:07.000Z").unwrap(), 500);
        assert_eq!(seek_offset_before(&c, "2026-01-01T00:00:10.000Z").unwrap(), 900);
        assert_eq!(seek_offset_before(&c, "2025-01-01T00:00:00.000Z").unwrap(), 0);
        let latest = latest_checkpoints(&c).unwrap();
        assert_eq!(latest, vec![("*".into(), "2026-01-01T00:00:10.000Z".into())]);
    }
}

//! Ingest: tails the capture log into the SQLite index.
//!
//! Each [`Ingester::step`] reads a bounded batch of complete log lines starting at
//! the persisted offset. It writes everything it derives from them and the new
//! offset in **one transaction**. If the process dies before the commit, nothing
//! from the batch is visible and the next start re-reads the same bytes. If it
//! dies after the commit, the offset already covers the batch. Either way there
//! are no gaps and no duplicates.
//!
//! Stage 1 derives log checkpoints (seek points for `query text`). Session
//! reconstruction is added on top of the same step in a later stage.

use crate::eventlog::LogReader;
use crate::store::{self, GLOBAL_CHECKPOINT_APP};
use crate::timefmt::{self, Millis};
use anyhow::{Context, Result};
use rusqlite::Connection;
use std::collections::HashMap;
use std::path::{Path, PathBuf};

/// Minimum spacing between two checkpoints for the same app, in log time.
pub const CHECKPOINT_INTERVAL_MS: Millis = 5_000;
/// Upper bound on lines per transaction, which bounds memory use and commit latency.
pub const MAX_LINES_PER_STEP: usize = 5_000;

pub struct Ingester {
    conn: Connection,
    log_path: PathBuf,
    offset: u64,
    last_checkpoint: HashMap<String, Millis>,
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub struct StepStats {
    pub lines: usize,
    pub invalid_lines: usize,
    pub checkpoints: usize,
}

impl Ingester {
    pub fn new(conn: Connection, log_path: &Path) -> Result<Self> {
        let offset = store::ingest_offset(&conn)?;
        let mut last_checkpoint = HashMap::new();
        for (app, ts) in store::latest_checkpoints(&conn)? {
            if let Ok(ms) = timefmt::parse_rfc3339_ms(&ts) {
                last_checkpoint.insert(app, ms);
            }
        }
        Ok(Self { conn, log_path: log_path.to_owned(), offset, last_checkpoint })
    }

    pub fn offset(&self) -> u64 {
        self.offset
    }

    /// Ingests at most [`MAX_LINES_PER_STEP`] new complete lines.
    /// Returns `lines == 0` when caught up.
    pub fn step(&mut self) -> Result<StepStats> {
        if !self.log_path.exists() {
            return Ok(StepStats::default());
        }
        let mut reader = LogReader::open(&self.log_path, self.offset)?;
        let mut stats = StepStats::default();
        // Checkpoint decisions are staged in memory and only applied to
        // `self.last_checkpoint` once the transaction commits.
        let mut pending: Vec<(String, Millis, u64)> = Vec::new();
        let mut staged_last: HashMap<&str, Millis> = HashMap::new();

        let tx = self.conn.transaction().context("starting ingest transaction")?;
        while stats.lines < MAX_LINES_PER_STEP {
            let Some(line) = reader.next_line()? else { break };
            stats.lines += 1;
            let Some(event) = line.event else {
                stats.invalid_lines += 1;
                continue;
            };
            for app in [GLOBAL_CHECKPOINT_APP, event.app.as_str()] {
                let last = staged_last
                    .get(app)
                    .copied()
                    .or_else(|| self.last_checkpoint.get(app).copied());
                let due = match last {
                    None => true,
                    // `abs` so a backwards clock jump does not suppress checkpoints for long.
                    Some(prev) => (event.ts - prev).abs() >= CHECKPOINT_INTERVAL_MS,
                };
                if due {
                    store::insert_checkpoint(&tx, app, &timefmt::format_ms(event.ts), line.offset)?;
                    pending.push((app.to_owned(), event.ts, line.offset));
                    stats.checkpoints += 1;
                    let key: &str = if app == GLOBAL_CHECKPOINT_APP {
                        GLOBAL_CHECKPOINT_APP
                    } else {
                        // Borrow from `pending` is awkward here; leak-free owned key below.
                        &pending.last().expect("just pushed").0
                    };
                    // SAFETY-free trick avoided: re-insert using owned copy instead.
                    let _ = key;
                    staged_last.insert(
                        if app == GLOBAL_CHECKPOINT_APP { GLOBAL_CHECKPOINT_APP } else { "" },
                        event.ts,
                    );
                }
            }
        }
        if stats.lines == 0 {
            return Ok(stats); // nothing to commit; tx rolls back (no-op)
        }
        let new_offset = reader.offset();
        store::set_ingest_offset(&tx, new_offset)?;
        tx.commit().context("committing ingest transaction")?;

        self.offset = new_offset;
        for (app, ts, _) in pending {
            self.last_checkpoint.insert(app, ts);
        }
        Ok(stats)
    }

    /// Steps until caught up with the log (or `max_steps` reached).
    pub fn catch_up(&mut self, max_steps: usize) -> Result<StepStats> {
        let mut total = StepStats::default();
        for _ in 0..max_steps {
            let s = self.step()?;
            total.lines += s.lines;
            total.invalid_lines += s.invalid_lines;
            total.checkpoints += s.checkpoints;
            if s.lines < MAX_LINES_PER_STEP {
                break;
            }
        }
        Ok(total)
    }
}

