}

impl Drop for Keyboard {
    fn drop(&mut self) {
        // SAFETY: each pointer is owned and released exactly once.
        unsafe {
            xkb_state_unref(self.state.as_ptr());
            xkb_keymap_unref(self.keymap.as_ptr());
            xkb_context_unref(self.ctx.as_ptr());
