    }

    #[test]
    fn caps_lock_is_reflected_in_char_not_mods() {
        let mut kb = us();
        kb.update_key(KEY_CAPSLOCK, true);
        kb.update_key(KEY_CAPSLOCK, false);
        assert_eq!(press(&mut kb, KEY_A), (Some("A".into()), vec![]));
    }

    #[test]
    fn ctrl_combo_keeps_the_letter() {
        let mut kb = us();
