input.content:
//! The recorder: the one place where events are stamped with focus and appended to the log.
//!
//! Shared between the input thread (keys, clicks, pastes) and the D-Bus
//! threads (focus changes, lock/sleep markers). A mutex around the log writer
//! serializes appends, so lines never interleave.

use crate::event::{Event, EventKind, Mod, SystemState, UNKNOWN_APP};
use crate::eventlog::LogWriter;
use crate::timefmt::{Millis, now_ms};
use anyhow::Result;
use std::sync::Mutex;
use std::sync::atomic::{AtomicU64, Ordering};

/// Upper bound on recorded clipboard text per paste, in bytes. Larger pastes
/// are truncated at a character boundary. This keeps one paste from
/// ballooning the log or the process's memory.
pub const MAX_PASTE_BYTES: usize = 64 * 1024;

/// Reads the clipboard at paste time.
pub trait ClipboardSource: Send + Sync {
    fn read(&self) -> Option<String>;
}

pub struct NoClipboard;
impl ClipboardSource for NoClipboard {
    fn read(&self) -> Option<String> {
        None
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Focus {
    pub app: String,
    pub window: String,
}

impl Default for Focus {
    fn default() -> Self {
        Self { app: UNKNOWN_APP.to_string(), window: String::new() }
    }
}

struct Inner {
    log: LogWriter,
    focus: Focus,
    paused: bool,
}

pub struct Recorder {
    inner: Mutex<Inner>,
    clipboard: Box<dyn ClipboardSource>,
    write_errors: AtomicU64,
}

impl Recorder {
    pub fn new(log: LogWriter, clipboard: Box<dyn ClipboardSource>) -> Self {
        Self {
            inner: Mutex::new(Inner { log, focus: Focus::default(), paused: false }),
            clipboard,
            write_errors: AtomicU64::new(0),
        }
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, Inner> {
        // A panic while holding the lock cannot leave the log half-written
        // (appends are single writes), so recovering from poisoning is safe.
        self.inner.lock().unwrap_or_else(|p| p.into_inner())
    }

    fn append(&self, inner: &mut Inner, event: Event) {
        if let Err(e) = inner.log.append(&event) {
            // Never take capture down over a write error (for example, the disk
            // is full). Report the first one, then every 1000th.
            let n = self.write_errors.fetch_add(1, Ordering::Relaxed);
            if n % 1000 == 0 {
                eprintln!("brain: failed to write capture log ({} errors so far): {e:#}", n + 1);
            }
        }
    }

    pub fn focus(&self) -> Focus {
        self.lock().focus.clone()
    }

    /// Records a focus change. A no-op if neither app nor window changed.
    pub fn set_focus(&self, app: &str, window: &str) {
        let mut g = self.lock();
        if g.focus.app == app && g.focus.window == window {
            return;
        }
        g.focus = Focus { app: app.to_string(), window: window.to_string() };
        if g.paused {
            return; // recorded on unlock, when it matters
        }
        let ev = Event { ts: now_ms(), app: app.to_string(), kind: EventKind::Focus { window: window.to_string() } };
        self.append(&mut g, ev);
    }

    /// Pauses or resumes recording of input (screen lock). Lifecycle markers
    /// are still written.
    pub fn set_paused(&self, paused: bool) {
        let mut g = self.lock();
        if g.paused == paused {
            return;
        }
        g.paused = paused;
        let app = g.focus.app.clone();
        let state = if paused { SystemState::Lock } else { SystemState::Unlock };
        self.append(&mut g, Event { ts: now_ms(), app: app.clone(), kind: EventKind::System { state } });
        if !paused {
            // Re-state the focus so readers know the context after the gap.
            let window = g.focus.window.clone();
            self.append(&mut g, Event { ts: now_ms(), app, kind: EventKind::Focus { window } });
        }
    }

    pub fn is_paused(&self) -> bool {
        self.lock().paused
    }

    pub fn system(&self, state: SystemState) {
        let mut g = self.lock();
        let app = g.focus.app.clone();
        self.append(&mut g, Event { ts: now_ms(), app, kind: EventKind::System { state } });
    }

    /// Records a key. If it is a paste shortcut, the clipboard is read (outside
    /// the lock) and written as a `paste` event right after it.
    pub fn key(&self, ts: Millis, key: String, mods: Vec<Mod>, repeat: bool) {
        let paste = is_paste_shortcut(&key, &mods);
        let focus = {
            let mut g = self.lock();
            if g.paused {
                return;
            }
            let Focus { app, window } = g.focus.clone();
            let ev = Event { ts, app: app.clone(), kind: EventKind::Key { key, mods, repeat, window: window.clone() } };
            self.append(&mut g, ev);
            Focus { app, window }
        };
        if paste {
            let text = self.clipboard.read().map(|t| truncate_utf8(t, MAX_PASTE_BYTES));
            let mut g = self.lock();
            let ev = Event { ts, app: focus.app, kind: EventKind::Paste { text, window: focus.window } };
            self.append(&mut g, ev);
        }
    }

    pub fn click(&self, ts: Millis, button: &str) {
        let mut g = self.lock();
        if g.paused {
            return;
        }
        let Focus { app, window } = g.focus.clone();
        self.append(&mut g, Event { ts, app, kind: EventKind::Click { button: button.to_string(), window } });
    }

    /// fdatasync the log if anything was appended since the last call.
    pub fn sync(&self) -> Result<()> {
        self.lock().log.sync()
    }
}

/// Ctrl+V, Ctrl+Shift+V (terminals) and Shift+Insert.
pub fn is_paste_shortcut(key: &str, mods: &[Mod]) -> bool {
    match key {
        "v" | "V" => mods == [Mod::Ctrl] || mods == [Mod::Shift, Mod::Ctrl],
        "Insert" => mods == [Mod::Shift],
        _ => false,
    }
}

fn truncate_utf8(mut s: String, max: usize) -> String {
    if s.len() > max {
        let mut cut = max;
        while !s.is_char_boundary(cut) {
            cut -= 1;
        }
        s.truncate(cut);
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::eventlog::LogReader;

    struct FixedClipboard(&'static str);
    impl ClipboardSource for FixedClipboard {
        fn read(&self) -> Option<String> {
            Some(self.0.to_string())
        }
    }

    fn events(path: &std::path::Path) -> Vec<Event> {
        let mut r = LogReader::open(path, 0).unwrap();
        let mut v = Vec::new();
        while let Some(l) = r.next_line().unwrap() {
            v.push(l.event.unwrap());
        }
        v
    }

    #[test]
    fn stamps_focus_and_handles_paste_and_lock() {
        let tmp = tempfile::tempdir().unwrap();
        let p = tmp.path().join("events.jsonl");
        let rec = Recorder::new(LogWriter::open(&p).unwrap(), Box::new(FixedClipboard("pasted")));
        rec.set_focus("code", "main.rs");
        rec.set_focus("code", "main.rs"); // duplicate: no event
        rec.key(10, "h".into(), vec![], false);
        rec.key(11, "v".into(), vec![Mod::Ctrl], false);
        rec.set_paused(true);
        rec.key(12, "s".into(), vec![], false); // lock-screen password: dropped
        rec.set_focus("org.kde.konsole", "bash"); // remembered, not written
        rec.set_paused(false);
        rec.click(13, "left");

        let evs = events(&p);
        let kinds: Vec<String> = evs
            .iter()
            .map(|e| match &e.kind {
                EventKind::Key { key, window, .. } => format!("{}:key:{key}@{window}", e.app),
                EventKind::Focus { window } => format!("{}:focus@{window}", e.app),
                EventKind::Paste { text, .. } => format!("{}:paste:{}", e.app, text.as_deref().unwrap_or("-")),
                EventKind::Click { button, window } => format!("{}:click:{button}@{window}", e.app),
                EventKind::System { state } => format!("{}:{state:?}", e.app),
            })
            .collect();
        assert_eq!(
            kinds,
            vec![
                "code:focus@main.rs",
                "code:key:h@main.rs",
                "code:key:v@main.rs",
                "code:paste:pasted",
                "code:Lock",
                "org.kde.konsole:Unlock",
                "org.kde.konsole:focus@bash",
                "org.kde.konsole:click:left@bash",
            ]
        );
    }

    #[test]
    fn paste_shortcuts() {
        assert!(is_paste_shortcut("v", &[Mod::Ctrl]));
        assert!(is_paste_shortcut("V", &[Mod::Shift, Mod::Ctrl]));
        assert!(is_paste_shortcut("Insert", &[Mod::Shift]));
        assert!(!is_paste_shortcut("v", &[]));
        assert!(!is_paste_shortcut("v", &[Mod::Ctrl, Mod::Alt]));
    }

    #[test]
    fn truncation_respects_char_boundaries() {
        assert_eq!(truncate_utf8("héllo".into(), 2), "h");
        assert_eq!(truncate_utf8("abc".into(), 10), "abc");
    }
}

//! The input thread: reads every keyboard and pointer device with one `poll(2)` loop.
//!
//! * **Passive.** Devices are opened read-only and never grabbed, so the
//!   compositor receives every event exactly as before. `brain` cannot add
//!   input lag, whatever it does.
//! * **Cheap.** Each device gets an evdev event mask (`EVIOCSMASK`) so the
//!   kernel only wakes us for key/button transitions. Pointer motion, scroll,
//!   and `MSC_SCAN` never reach userspace. When nothing is pressed, the thread
//!   sleeps in `poll` with no timeout.
//! * **Robust.** `/dev/input` is watched with inotify for hotplug. A vanished
//!   device releases its held keys. On resume from sleep, every device is
//!   closed and re-opened.

use super::keys::{KeyOut, KeyProcessor};
use super::recorder::Recorder;
use crate::timefmt::{Millis, now_ms, system_time_ms};
use anyhow::{Context, Result, bail};
use evdev::{EventType, KeyCode, RawDevice};
use std::collections::{HashMap, HashSet};
use std::ffi::CString;
use std::os::fd::{AsRawFd, FromRawFd, OwnedFd, RawFd};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::sync::mpsc::{Receiver, Sender};

const INPUT_DIR: &str = "/dev/input";
/// A touchpad touch shorter than this counts as a tap (a click, when
/// tap-to-click is on). Longer touches are pointer motion or scrolling.
const TAP_MAX_MS: Millis = 250;

// evdev codes not exported as consts we can match on.
const SYN_DROPPED: u16 = 3;

/// Messages from other threads to the input thread.
#[derive(Debug)]
pub enum Control {
    /// Close and re-open all devices (after resume from sleep).
    Reopen,
    /// KDE's layout switcher changed the active layout.
    SetLayout(u32),
    /// Replace the keymap (the layout list changed).
    SetKeyboard(Box<super::xkb::Keyboard>),
    Stop,
}

/// Sends [`Control`] messages and wakes the input thread's `poll`.
#[derive(Clone)]
pub struct ControlHandle {
    tx: Sender<Control>,
    wake: Arc<OwnedFd>,
}

impl ControlHandle {
    pub fn send(&self, msg: Control) {
        if self.tx.send(msg).is_ok() {
            let one: u64 = 1;
            // SAFETY: writing 8 bytes to a valid eventfd.
            unsafe { libc::write(self.wake.as_raw_fd(), (&one as *const u64).cast(), 8) };
        }
    }
}

#[derive(Debug, Clone, Copy, Default)]
struct Kind {
    keyboard: bool,
    pointer: bool,
    /// Has BTN_TOOL_FINGER: a touchpad, where BTN_TOUCH means a finger is down.
    touchpad: bool,
    /// BTN_TOUCH without BTN_TOOL_FINGER: a touchscreen, where a touch is a click.
    touchscreen: bool,
}

struct Device {
    id: u32,
    path: PathBuf,
    dev: RawDevice,
    kind: Kind,
    touch_down_at: Option<Millis>,
}

pub struct InputLoop {
    devices: Vec<Device>,
    next_id: u32,
    inotify: OwnedFd,
    wake: Arc<OwnedFd>,
    rx: Receiver<Control>,
    keys: KeyProcessor,
    recorder: Arc<Recorder>,
    /// Paths that failed with EACCES, reported once.
    denied: HashSet<PathBuf>,
}

impl InputLoop {
    pub fn new(keys: KeyProcessor, recorder: Arc<Recorder>) -> Result<(Self, ControlHandle)> {
        // SAFETY: plain syscalls; return values are checked.
        let wake = unsafe { libc::eventfd(0, libc::EFD_NONBLOCK | libc::EFD_CLOEXEC) };
        if wake < 0 {
            return Err(std::io::Error::last_os_error()).context("eventfd");
        }
        // SAFETY: `wake` is a fresh, owned fd.
        let wake = Arc::new(unsafe { OwnedFd::from_raw_fd(wake) });
        let inotify = unsafe { libc::inotify_init1(libc::IN_NONBLOCK | libc::IN_CLOEXEC) };
        if inotify < 0 {
            return Err(std::io::Error::last_os_error()).context("inotify_init1");
        }
        // SAFETY: fresh, owned fd.
        let inotify = unsafe { OwnedFd::from_raw_fd(inotify) };
        let dir = CString::new(INPUT_DIR).unwrap();
        // IN_ATTRIB: udev applies the `input` group permissions after creating
        // the node, so a device may only become openable on that event.
        let wd = unsafe {
            libc::inotify_add_watch(inotify.as_raw_fd(), dir.as_ptr(), libc::IN_CREATE | libc::IN_ATTRIB)
        };
        if wd < 0 {
            return Err(std::io::Error::last_os_error()).context("watching /dev/input");
        }
        let (tx, rx) = std::sync::mpsc::channel();
        let handle = ControlHandle { tx, wake: wake.clone() };
        let me = Self {
            devices: Vec::new(),
            next_id: 0,
            inotify,
            wake,
            rx,
            keys,
            recorder,
            denied: HashSet::new(),
        };
        Ok((me, handle))
    }

    /// Opens all current devices. Fails if there are input devices but none can
    /// be read, which almost always means missing permissions.
    pub fn open_initial(&mut self) -> Result<()> {
        self.scan();
        if !self.devices.iter().any(|d| d.kind.keyboard) {
            if !self.denied.is_empty() {
                bail!(
                    "permission denied reading {INPUT_DIR}/event*: add your user to the `input` \
                     group (`sudo usermod -aG input $USER`, then log out and back in)"
                );
            }
            eprintln!("brain: warning: no keyboard found yet; waiting for one to be plugged in");
        }
        Ok(())
    }

    pub fn keyboard_count(&self) -> usize {
        self.devices.iter().filter(|d| d.kind.keyboard).count()
    }

    /// Opens any `/dev/input/event*` node not already open.
    fn scan(&mut self) {
        let Ok(entries) = std::fs::read_dir(INPUT_DIR) else { return };
        let mut paths: Vec<PathBuf> = entries
            .filter_map(|e| e.ok())
            .map(|e| e.path())
            .filter(|p| p.file_name().and_then(|n| n.to_str()).is_some_and(|n| n.starts_with("event")))
            .collect();
        paths.sort();
        for path in paths {
            if self.devices.iter().any(|d| d.path == path) {
                continue;
            }
            match open_device(&path) {
                Ok(Some((dev, kind))) => {
                    self.denied.remove(&path);
                    let id = self.next_id;
                    self.next_id += 1;
                    self.devices.push(Device { id, path, dev, kind, touch_down_at: None });
                }
                Ok(None) => {} // not a keyboard or pointer
                Err(e) if e.kind() == std::io::ErrorKind::PermissionDenied => {
                    self.denied.insert(path);
                }
                Err(_) => {} // vanished or not ready yet; inotify will tell us again
            }
        }
    }

    fn close_all(&mut self) {
        for d in self.devices.drain(..) {
            self.keys.device_gone(d.id);
        }
        self.keys.release_all();
    }

    /// Runs until [`Control::Stop`].
    pub fn run(mut self) {
        let mut fds: Vec<libc::pollfd> = Vec::new();
        let mut gone: Vec<usize> = Vec::new();
        loop {
            fds.clear();
            fds.push(pollfd(self.wake.as_raw_fd()));
            fds.push(pollfd(self.inotify.as_raw_fd()));
            for d in &self.devices {
                fds.push(pollfd(d.dev.as_raw_fd()));
            }
            let timeout = match self.keys.deadline() {
                Some(at) => (at - now_ms()).clamp(0, i32::MAX as Millis) as i32,
                None => -1,
            };
            // SAFETY: `fds` is a valid array of pollfd for the duration of the call.
            let n = unsafe { libc::poll(fds.as_mut_ptr(), fds.len() as libc::nfds_t, timeout) };
            if n < 0 {
                let err = std::io::Error::last_os_error();
                if err.kind() == std::io::ErrorKind::Interrupted {
                    continue;
                }
                eprintln!("brain: poll failed: {err}");
                std::thread::sleep(std::time::Duration::from_millis(100));
                continue;
            }

            // Synthesized key repeats that came due while we slept.
            let rec = self.recorder.clone();
            self.keys.tick(now_ms(), &mut |k| emit(&rec, k));

            if fds[0].revents != 0 {
                drain_fd(self.wake.as_raw_fd());
                while let Ok(msg) = self.rx.try_recv() {
                    match msg {
                        Control::Stop => {
                            self.close_all();
                            return;
                        }
                        Control::Reopen => {
                            self.close_all();
                            self.scan();
                        }
                        Control::SetLayout(i) => self.keys.set_layout_index(i),
                        Control::SetKeyboard(kb) => self.keys.replace_keyboard(*kb),
                    }
                }
                continue; // device set may have changed; rebuild fds
            }
            if fds[1].revents != 0 {
                drain_fd(self.inotify.as_raw_fd());
                self.scan();
                continue;
            }

            gone.clear();
            for (i, pfd) in fds[2..].iter().enumerate() {
                if pfd.revents == 0 {
                    continue;
                }
                if pfd.revents & (libc::POLLERR | libc::POLLHUP | libc::POLLNVAL) != 0
                    && pfd.revents & libc::POLLIN == 0
                {
                    gone.push(i);
                    continue;
                }
                if !self.read_device(i) {
                    gone.push(i);
                }
            }
            for &i in gone.iter().rev() {
                let d = self.devices.remove(i);
                self.keys.device_gone(d.id);
            }
        }
    }

    /// Drains one device. Returns false if the device is gone.
    fn read_device(&mut self, idx: usize) -> bool {
        let rec = self.recorder.clone();
        let Self { devices, keys, .. } = self;
        let d = &mut devices[idx];
        let mut resync = false;
        loop {
            let events: Vec<evdev::InputEvent> = match d.dev.fetch_events() {
                Ok(it) => it.collect(),
                Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
                Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                Err(_) => return false, // ENODEV: unplugged
            };
            for ev in events {
                let ts = system_time_ms(ev.timestamp());
                if ev.event_type() == EventType::SYNCHRONIZATION && ev.code() == SYN_DROPPED {
                    resync = true;
                    continue;
                }
                if ev.event_type() != EventType::KEY {
                    continue;
                }
                let code = ev.code();
                let value = ev.value();
                if is_button(code) {
                    handle_button(d, code, value, ts, &rec);
                } else if d.kind.keyboard {
                    keys.key(d.id, code, value, ts, &mut |k| emit(&rec, k));
                }
            }
        }
        if resync {
            // The kernel buffer overflowed: re-read which keys are down.
            if let Ok(state) = d.dev.get_key_state() {
                let pressed: HashSet<u16> = state.iter().map(|k| k.code()).filter(|c| !is_button(*c)).collect();
                keys.resync(d.id, &pressed);
            }
        }
        true
    }
}

fn emit(rec: &Recorder, k: KeyOut) {
    rec.key(k.ts, k.key, k.mods, k.repeat);
}

fn handle_button(d: &mut Device, code: u16, value: i32, ts: Millis, rec: &Recorder) {
    let btn = KeyCode::new(code);
    if btn == KeyCode::BTN_LEFT || btn == KeyCode::BTN_RIGHT || btn == KeyCode::BTN_MIDDLE {
        if value == 1 && d.kind.pointer {
            let name = match btn {
                KeyCode::BTN_LEFT => "left",
                KeyCode::BTN_RIGHT => "right",
                _ => "middle",
            };
            rec.click(ts, name);
        }
    } else if btn == KeyCode::BTN_TOUCH {
        if d.kind.touchscreen {
            if value == 1 {
                rec.click(ts, "touch");
            }
        } else if d.kind.touchpad {
            match value {
                1 => d.touch_down_at = Some(ts),
                0 => {
                    if let Some(down) = d.touch_down_at.take() {
                        if ts - down <= TAP_MAX_MS {
                            rec.click(ts, "tap");
                        }
                    }
                }
                _ => {}
            }
        }
    }
}

/// BTN_* codes (mouse, joystick, touch) as opposed to keyboard keys.
fn is_button(code: u16) -> bool {
    (0x100..0x160).contains(&code) || code >= 0x2c0
}

fn classify(dev: &RawDevice) -> Kind {
    let Some(keys) = dev.supported_keys() else { return Kind::default() };
    let keyboard = [KeyCode::KEY_A, KeyCode::KEY_Z, KeyCode::KEY_SPACE, KeyCode::KEY_ENTER]
        .iter()
        .all(|k| keys.contains(*k));
    let pointer = keys.contains(KeyCode::BTN_LEFT);
    let has_touch = keys.contains(KeyCode::BTN_TOUCH);
    let touchpad = has_touch && keys.contains(KeyCode::BTN_TOOL_FINGER);
    let touchscreen = has_touch && !touchpad && dev.supported_events().contains(EventType::ABSOLUTE);
    Kind { keyboard, pointer, touchpad, touchscreen }
}

/// Opens a device if it is a keyboard or pointer. `Ok(None)` for other devices.
fn open_device(path: &Path) -> std::io::Result<Option<(RawDevice, Kind)>> {
    let dev = RawDevice::open(path)?;
    let kind = classify(&dev);
    if !(kind.keyboard || kind.pointer || kind.touchpad || kind.touchscreen) {
        return Ok(None);
    }
    let fd = dev.as_raw_fd();
    // SAFETY: fcntl on a valid fd.
    unsafe {
        let flags = libc::fcntl(fd, libc::F_GETFL);
        if flags < 0 || libc::fcntl(fd, libc::F_SETFL, flags | libc::O_NONBLOCK) < 0 {
