#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn button_ranges() {
        assert!(is_button(0x110)); // BTN_LEFT
        assert!(is_button(0x14a)); // BTN_TOUCH
        assert!(!is_button(30)); // KEY_A
