};
await key('End','End',35, 2); // ctrl+end
for (const c of 'abc(') await key(c, '', c.toUpperCase().charCodeAt(0), 0, c);
await key('Backspace','Backspace',8);
await key('Backspace','Backspace',8);
await key('s','KeyS',83, 2);
await new Promise(r=>setTimeout(r,800));
console.log(JSON.stringify((await send('Runtime.evaluate',{expression:'document.title'})).result));
process.exit(0);
EOF
cd $S && ELECTRON_RUN_AS_NODE=1 /usr/share/code/code t.mjs 2>&1 | tail -3; cp t.js t.mjs; ELECTRON_RUN_AS_NODE=1 /usr/share/code/code t.mjs 2>&1|tail -3; cat -A work/a.txt

