DROP TRIGGER IF EXISTS sessions_ad;
DROP TRIGGER IF EXISTS sessions_au;
DROP TABLE IF EXISTS sessions_fts;
DROP TABLE IF EXISTS sessions;
DROP TABLE IF EXISTS context_state;
DROP TABLE IF EXISTS ingest_state;
