/// The session's own input events: everything logged for its (app, window)
/// between its first and last event.
fn session_events(
    log_path: &Path,
    app: &str,
    window: &str,
    start: u64,
    end: u64,
) -> Result<Vec<ReplayEvent>> {
    let mut reader = LogReader::open(log_path, start)?;
